p.me:
\begin{array}{c|c|c}
\textbf{type} \amp \textbf{what happens} \amp \textbf{example}\\
\hline
\text{removable} \amp
\text{limit exists, but value is missing or wrong}
\amp
\displaystyle \frac{x^2-1}{x-1}\text{ at }x=1\\
\text{jump} \amp
\text{left and right limits disagree}
\amp
\displaystyle \frac{|x|}{x}\text{ at }x=0\\
\text{infinite} \amp
\text{values grow without bound}
\amp
\displaystyle \frac{1}{(x-2)^2}\text{ at }x=2
\end{array}

